PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?var1 ?var2 ?var3 ?var4 ?var5 ?var6
WHERE
  { ?var1  wdt:P31     wde:Q5 ;
           wdt:P569    ?var4 ;
           wdt:P570    ?var5 ;
           wdt:P19     ?var6 ;
           wdt:P646    ?var3 ;
           rdfs:label  ?var2
    FILTER ( lang(?var2) = "en" )
